using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.UI;using Assets.Script.DynamicCards;
public static class MotionWork{static object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);static string RectIn(RectTransform r,RectTransform basis){var a=new Vector3[4];r.GetWorldCorners(a);return string.Join(";",a.Select(x=>basis.InverseTransformPoint(x).ToString("F3")));}public static void Run(){var rows=new System.Collections.Generic.List<string>();foreach(var v in UnityEngine.Object.FindObjectsOfType<DynamicCardView>()){var cam=(Camera)F(v,"renderCamera");var model=(GameObject)F(v,"model");if(cam==null||model==null)continue;var raw=(RawImage)F(v,"surface");var art=(Image)F(v,"art");var big=art.GetComponentInParent<ArtCard>();var small=art.GetComponentInParent<CardShowInfo>();var border=big!=null?big.CardBorder:small.CardBorder;rows.Add(F(v,"artId")+" preview="+F(v,"preview")+" cameraLocal="+model.transform.InverseTransformPoint(cam.transform.position).ToString("F6")+" cameraRot="+cam.transform.rotation.ToString("F6")+" modelRot="+model.transform.rotation.ToString("F6")+" pivot="+((Transform)F(v,"pivot")).localRotation.ToString("F6")+" projection="+cam.projectionMatrix.ToString("F6")+" uv="+raw.uvRect+" artRect="+art.rectTransform.rect+" borderRect="+border.rectTransform.rect+" surfaceInBorder="+RectIn(raw.rectTransform,border.rectTransform)+" preserveAspect="+art.preserveAspect+" imageType="+art.type);}File.WriteAllLines("C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/ScrollAndFramingRepair/camera-ui-fixed.txt",rows);}}
